<script lang="ts">
  import { companion,updateData,notify } from '../state.svelte';
  import { chatState,connectGateway,refreshGateway,syncPersonalLore,clearAllLocalData } from '../bridge.svelte';
  import { DBState } from '../../ts/stores.svelte';
  import { getModelInfo, LLMModels } from '../../ts/model/modellist';
  import { forageStorage } from '../../ts/globalApi.svelte';
  import {voiceProfiles} from '../voice';
  import {playRoomVoice} from '../sound';
  import {appearanceMode} from '../theme';
  import AppearanceSettings from '../components/AppearanceSettings.svelte';
  import PixelBento from '../components/PixelBento.svelte';
  import LockSettings from '../components/LockSettings.svelte';
  import ConfirmDialog from '../components/ConfirmDialog.svelte';
  let deletePhrase=$state('');
  let confirm=$state<{title:string;description:string;label?:string;destructive?:boolean;action:()=>void|Promise<void>}|null>(null);
  let modelName=$derived(getModelInfo(DBState.db.aiModel)?.name||DBState.db.aiModel);
  async function perform(action:()=>void|Promise<void>){try{await action();}catch(e){notify(String(e).replace(/^Error: /,''));}}
  function toggle(key:'memoryEnabled'|'profileEnabled'|'analysisEnabled'){
    if(companion.data.preferences[key]){updateData(data=>data.preferences[key]=false);syncPersonalLore();notify('已关闭，已有记录仍可查看或删除。');return;}
    const name={memoryEnabled:'长期记忆',profileEnabled:'画像参与',analysisEnabled:'对话情绪分析'}[key];
    confirm={title:'开启'+name+'？',description:key==='analysisEnabled'?'回复完成后，最近八条消息将再次发往所选模型，生成情绪参考记录。只有单独开启画像时才会留下待确认画像。你可以随时撤销。':'仅你主动保存或确认的内容用于陪伴；会随相关上下文发送给所选模型，随时可撤销或删除。',label:'我了解，开启',action:()=>{updateData(data=>data.preferences[key]=true);syncPersonalLore();}};
  }
</script>
<div class="xy-page-heading"><div><h1>我的小岛</h1><p>在自己的空间，选择舒服的陪伴方式。</p></div></div>
<PixelBento className="settings-grid" reduced={companion.data.preferences.reduceMotion}><section class="xy-panel settings-profile"><h2>我的资料</h2><div class="settings-identity"><img src="/xinyu/art/girl_card.png" alt=""/><div><strong>{companion.data.preferences.name||'小岛主人'}</strong><span>本机个人空间</span></div></div><label for="settings-name">喜欢的称呼</label><input class="xy-input" id="settings-name" value={companion.data.preferences.name} maxlength="30" placeholder="小屿该怎么称呼你？" onchange={(e)=>perform(()=>updateData(data=>data.preferences.name=e.currentTarget.value.trim().slice(0,30)))}/></section>
  <section class="xy-panel model-settings" tabindex="-1"><h2>模型连接</h2><div class="connection-line"><span class:connected={chatState.gatewayReady} class="connection-dot"></span><strong>{chatState.gatewayReady?'本机网关已配置':'本机网关未配置'}</strong><button class="text-button" onclick={refreshGateway}>刷新</button></div><p>当前模型：<strong>{modelName}</strong></p><p class="quiet-note">密钥保留在服务端。可在下方选择对话模型。</p><div class="xy-actions"><button class="xy-btn primary" disabled={!chatState.gatewayReady||chatState.busy} onclick={()=>perform(()=>connectGateway())}>使用本机网关</button></div><details><summary>已有模型快捷切换</summary><label for="active-model" class="sr-only">当前聊天模型</label><select id="active-model" value={DBState.db.aiModel} disabled={chatState.busy} onchange={(e)=>{DBState.db.aiModel=e.currentTarget.value;notify('已切换聊天模型，请确认已配置对应凭据。');}}>{#each [...DBState.db.customModels.map(m=>({id:m.id,name:m.name})),...LLMModels.filter(m=>['openai','deepseek-chat','deepseek-reasoner','gpt-4o-mini','gemini-3-flash-preview'].includes(m.id)),...(DBState.db.customModels.some(m=>m.id===DBState.db.aiModel)||LLMModels.some(m=>m.id===DBState.db.aiModel)?[]:[{id:DBState.db.aiModel,name:modelName}])] as model}<option value={model.id}>{model.name}</option>{/each}</select></details></section>
  <section class="xy-panel privacy-settings"><h2>隐私与授权</h2>{#each [{key:'memoryEnabled',name:'长期记忆',description:'只保存你明确同意留下的内容'},{key:'profileEnabled',name:'画像参与陪伴',description:'只有确认的偏好会进入对话上下文'},{key:'analysisEnabled',name:'对话情绪分析',description:'将最近八条消息发给所选模型作参考分析'}] as item}<div class="setting-row"><div><strong>{item.name}</strong><p>{item.description}</p></div><button class="xy-switch" role="switch" aria-checked={companion.data.preferences[item.key]} aria-label={item.name} onclick={()=>toggle(item.key as 'memoryEnabled'|'profileEnabled'|'analysisEnabled')}><i></i></button></div>{/each}<p class="quiet-note">{forageStorage.isAccount?'云同步已开启，个人记录会随存档同步。请在对应服务中管理云端副本。':'当前记录保存在此浏览器。'}</p><a class="text-link" href="/xinyu/privacy.html" target="_blank" rel="noreferrer">查看完整隐私说明 →</a></section>
  <section class="xy-panel appearance-settings"><h2>窗外与光线</h2><AppearanceSettings section="visual"/></section><section class="xy-panel sound-settings"><h2>声音与陪伴</h2><AppearanceSettings section="voice"/><div class="setting-row"><div><strong>底部导航自动隐藏</strong><p>开启后将鼠标移到屏幕底部，或用键盘唤出导航</p></div><button class="xy-switch" role="switch" aria-checked={companion.data.preferences.dockAutoHide!==false} aria-label="底部导航自动隐藏" onclick={()=>perform(()=>updateData(data=>data.preferences.dockAutoHide=!(data.preferences.dockAutoHide!==false)))}><i></i></button></div><div class="setting-row"><div><strong>互动语音</strong><p>小屿使用中文人声，猫咪使用猫叫；默认关闭</p></div><button class="xy-switch" role="switch" aria-checked={companion.data.preferences.sound} aria-label="互动语音" onclick={()=>perform(()=>updateData(data=>data.preferences.sound=!data.preferences.sound))}><i></i></button></div><div class="setting-row"><div><strong>环境背景音</strong><p>窗边雨雪声；与角色互动语音分别控制</p></div><button class="xy-switch" role="switch" aria-checked={companion.data.preferences.ambientSound===true} aria-label="环境背景音" onclick={()=>perform(()=>updateData(data=>data.preferences.ambientSound=!data.preferences.ambientSound))}><i></i></button></div><div class="setting-row"><div><strong>减少动态效果</strong><p>停止云朵和眨眼动画，交互仍可使用</p></div><button class="xy-switch" role="switch" aria-checked={companion.data.preferences.reduceMotion} aria-label="减少动态效果" onclick={()=>perform(()=>updateData(data=>data.preferences.reduceMotion=!data.preferences.reduceMotion))}><i></i></button></div><div class="xy-actions"><a class="xy-btn" href="#/avatar">选择形象</a><a class="xy-btn" href="#/scenes">更换窗景</a></div></section>
  <LockSettings/>
  <section class="xy-panel data-settings"><h2>本机记录管理</h2><p>只在需要重新开始时，清除这个浏览器中的记录。</p><div class="data-danger"><h3>清除全部本机数据</h3><p>包括所有角色、对话、心屿记录、模型配置与本机备份。不会清除已下载的文件或第三方服务中的副本。</p><label for="delete-phrase">输入“清除全部”以继续</label><input class="xy-input" id="delete-phrase" bind:value={deletePhrase} autocomplete="off"/><button class="xy-btn danger" disabled={deletePhrase!=='清除全部'||chatState.busy} onclick={()=>{confirm={destructive:true,title:'确定清除全部本机数据？',description:'所有对话、心情、记忆、画像、配置与本机备份将删除。此操作无法撤销。',label:'清除全部本机数据',action:clearAllLocalData};}}>清除全部本机数据</button></div></section>
  <section class="xy-panel about-settings"><h2>关于心屿智伴</h2><p>让每一种情绪都有回声。</p><div><a href="/xinyu/terms.html" target="_blank" rel="noreferrer">使用条款</a><a href="/xinyu/privacy.html" target="_blank" rel="noreferrer">隐私说明</a></div><a href="/xinyu/credits.html" target="_blank" rel="noreferrer">素材与开源许可</a></section></PixelBento>
{#if confirm}<ConfirmDialog destructive={confirm.destructive} title={confirm.title} description={confirm.description} confirmText={confirm.label||'确认'} onconfirm={confirm.action} onclose={()=>confirm=null}/>{/if}
